void inorder(TreeNode* root, vector<int>& result) {

    if (!root) return;

    inorder(root->left, result);   // 1. Go left
    result.push_back(root->val);   // 2. Visit root
    inorder(root->right, result);  // 3. Go right
}

vector<int> inorder(TreeNode* root) {
    vector<int> result;
    stack<TreeNode*> st;
    TreeNode* curr = root;

    while (curr || !st.empty()) {
        // Go as far left as possible
        while (curr) {
            st.push(curr);
            curr = curr->left;
        }
        // Pop and visit
        curr = st.top(); st.pop();
        result.push_back(curr->val);
        // Move to right subtree
        curr = curr->right;
    }
    return result;
}

class Solution {
public:
    long long prev = LLONG_MIN;

    bool inorder(TreeNode* node) {
        if (!node) return true;

        if (!inorder(node->left))
            return false;

        if (node->val <= prev)
            return false;

        prev = node->val;

        return inorder(node->right);
    }

    bool isValidBST(TreeNode* root) {
        return inorder(root);
    }
};

void reverseInorder(TreeNode* root, vector<int>& result) {

    if (!root) return;

    reverseInorder(root->right, result); // Right
    result.push_back(root->val);         // Root
    reverseInorder(root->left, result);  // Left
}
